var animating = !1,
    submitPhase1 = 0,
    submitPhase2 = 0,
    logoutPhase1 = 0,
    $login = document.querySelector(".login"),
    $status = document.querySelector("#status"),
    $loginSubmit = document.querySelector(".login-submit"),
    $logoutSubmit = document.querySelector(".logout-submit"),
    loggedIn = !1,
    intervalStatus = !1;

// دوال مساعدة
function showAlert(msg) {
    // استبدل هذه الدالة بأي نافذة تنبيه تحبها (swal أو alert)
    if (typeof swal === "function") {
        swal({ title: "تنبيه", text: msg, confirmText: "حسناً" });
    } else {
        alert(msg);
    }
}

function hideLoadingIndicator() {
    // مكان لتعطيل أي مؤشر تحميل إذا كان موجودًا
}

function showParentElement(e, t) {
    e.classList.add("success");
    setTimeout(function () {
        t.style.display = "block";
        getComputedStyle(t).top;
        t.classList.add("active");
    }, submitPhase2 - 70);
    setTimeout(function () {
        hideLoginPage();
        animating = !1;
        e.classList.remove("success", "processing");
    }, submitPhase2);
}

function hideLoginPage() {
    $login.style.display = "none";
    $login.classList.add("inactive");
}

function showLoginPage() {
    $login.style.display = "block";
    getComputedStyle($login).top;
    $login.classList.remove("inactive");
}

function initHotspotEvents(e, t) {
    var n, i = t.querySelectorAll(".app-logout");
    e.addEventListener("click", function (ev) {
        if (!animating) {
            animating = !0;
            this.classList.add("processing");
            showParentElement(this, t);
        }
    });
    for (n in i) {
        var o = i[n];
        if (typeof o === "object") {
            o.addEventListener("click", function (ev) {
                if (!animating) {
                    animating = !0;
                    var btn = this;
                    setTimeout(function () {
                        t.classList.remove("active");
                        showLoginPage();
                    }, submitPhase2 + 120);
                    setTimeout(function () {
                        t.style.display = "none";
                        animating = !1;
                        btn.classList.remove("processing");
                    }, submitPhase2);
                }
            });
        }
    }
}

// تحويلات عربية
function toArabicTime(e) {
    if (e === "") return "";
    var t = e;
    var n = "", i = "", o = "", s = "";
    if (e.indexOf("d") >= 0) {
        t = e.split("d");
        n = (t[0] !== "" ? t[0] + " يوم" : "");
        t = t[1];
    }
    if (e.indexOf("h") >= 0) {
        t = t.split("h");
        i = (t[0] !== "" ? t[0] + " ساعة" : "");
        t = t[1];
    }
    if (e.indexOf("m") >= 0) {
        t = t.split("m");
        o = (t[0] !== "" ? t[0] + " دقيقة" : "");
        t = t[1];
    }
    if (e.indexOf("s") >= 0) {
        t = t.split("s");
        s = (t[0] !== "" ? t[0] + " ثانية" : "");
    }
    var parts = [n, i, o, s].filter(Boolean);
    return parts.join(" و ");
}

function toArabicBytes(e) {
    if (e < 1024) {
        return e + " بايت";
    } else if (e < 1048576) {
        return Math.floor(e / 1024) + " كيلوبايت";
    } else if (e < 1073741824) {
        const mb = Math.floor(e / 1048576);
        const kb = Math.floor((e % 1048576) / 1024);
        return mb + " ميجا" + (kb > 0 ? " و " + kb + " كيلوبايت" : "");
    } else {
        const gb = Math.floor(e / 1073741824);
        const mb = Math.floor((e % 1073741824) / 1048576);
        return gb + " جيجا" + (mb > 0 ? " و " + mb + " ميجا" : "");
    }
}

function toArabicError(error) {
    var errorsMap = {
        "simultaneous session limit reached": "هذا الكرت متصل بالشبكة حالياً، إنتظر قليلاً وأعِد المحاولة",
        "invalid password": "الكرت الذي ادخلته غير موجود في النظام",
        "uptime limit reached": "عذراً لقد انتهى الوقت المتاح لك",
        "invalid username or password": "خطأ في اسم المستخدم أو كلمة المرور",
        "transfer limit reached": "لقد انتهى رصيد هذا الكرت",
        "no valid profile found": "لقد انتهت صلاحية هذا الكرت",
        "not found": "الكرت الذي ادخلته غير موجود في النظام",
        "invalid Calling-Station-Id": "هذا الكرت مرتبط بجهاز آخر، قم بإرسال المشكلة الى إدارة الشبكة لحل المشكلة",
        "no more sessions are allowed": "الكرت الذي تحاول الدخول به مسجل حالياً في الشبكة، تواصل بإدارة الشبكة لحل المشكلة",
        "server is not responding": "يرجى الانتظار، يتم الآن إعادة تشغيل الشبكة، هذه العملية قد تستغرق بعض الوقت",
        "web browser did not send": "يرجى محاولة إدخال الكرت مرة أخرى"
    };
    for (var key in errorsMap) {
        if (error.includes(key)) {
            return errorsMap[key];
        }
    }
    return "حصل خطأ: " + error;
}

// دوال التعامل مع الـ API
function onLoginError(e) {
    console.log("تم استدعاء onLoginError، الخطأ هو:", e);
    var usernameInput = document.querySelector("input[username-field]");
    var enteredCardNumber = usernameInput ? usernameInput.value : "";
    if (document.login && document.login.reset) {
        document.login.reset();
    }
    if (usernameInput) {
        usernameInput.value = enteredCardNumber;
    }
    $loginSubmit.classList.remove("success", "processing");
    animating = !1;
    var translatedError = toArabicError(e.error);
    document.getElementById("error").innerText = translatedError;

    // محاولة إضافة عدّاد محاولات إن وُجد كوكي أو سكربت مروّج
    try {
        var tryCount = parseInt(getCookieOrNull("hot_blocker_counter") || "0", 10);
        var blockerScript = document.querySelector("script[enable-hot-blocker]");
        var maxTries = blockerScript ? parseInt(blockerScript.getAttribute("try-count") || "5", 10) : 5;
        var remainingTries = maxTries - tryCount;
        if (remainingTries < 0) remainingTries = 0;
        translatedError += "\n\nالمحاولات المتبقية لك: " + remainingTries + " من " + maxTries + " محاولات ";
        if (remainingTries <= 2) {
            translatedError += "\n\nتحذير: لديك محاولة أخيرة قبل الحظر!";
        }
    } catch (err) {
        // تجاهل أخطاء العدّاد
    }

    // عرض رسالة ودية مع خيار إرسال تقرير (إن وُجد swal)
    if (typeof swal === "function") {
        var entered = enteredCardNumber || "";
        swal({
            title: "عزيزنا المشترك",
            text: translatedError,
            confirmText: "فهمت",
            reportText: "إرسال المشكلة لإدارة الشبكة !",
            onReport: function () {
                var smsBody = "السلام عليكم%0A" +
                    "المشكلة في تسجيل الدخول هي: " + encodeURIComponent(translatedError) + "%0A%0A" +
                    "رقم الكرت: " + encodeURIComponent(entered);
                // افتح تطبيق الرسائل (قد لا يعمل على كل المتصفحات)
                window.location.href = "SMS:737748525?body=" + smsBody;
            }
        });
    } else {
        showAlert(translatedError);
    }

    if (document.querySelector("script[enable-hot-blocker]")) {
        var t = incrementCounter && typeof incrementCounter === "function" ? incrementCounter(document.querySelector("script[enable-hot-blocker]")) : 0;
        if (typeof checkFailsCount === "function") checkFailsCount(document.querySelector("script[enable-hot-blocker]"), t);
    }
    clearCookies();
    hideLoadingIndicator();
}

function onLoggedIn(e) {
    resetCounter && typeof resetCounter === "function" && resetCounter();
    loggedIn = !0;
    showParentElement($loginSubmit, document.getElementById("status"));
    startStatusQuery();

    var usernameInput = document.querySelector("input[username-field]");
    if (usernameInput) {
        var username = usernameInput.value.trim();
        var isOnlyDigits = /^\d{5}$/.test(username);
        if (isOnlyDigits && typeof swal === "function") {
            swal({
                title: "🎉 ألف مبروك 🎉",
                text: "لقد ربحت كرت حظ، سيتم إضافته إلى الكرت الذي قمت الآن بتعبئته ✨",
                confirmText: "رائع!"
            });
        }
    }
}

function onLoggedOut(e) {
    loggedIn = !1;
}

function onStatusQuery(e) {
    if (e.logged_in) {
        for (var t in e) {
            var n = e[t];
            if (typeof n === "string" && "logged_in" !== t) {
                var i = document.getElementById(t);
                if (i != null) {
                    if (n === "") n = document.querySelector("[" + t + "]");
                    else if (t === "username") i.innerText = n;
                    else if (t.indexOf("bytes") !== -1) i.innerText = toArabicBytes(n);
                    else if (t.indexOf("time") !== -1) i.innerText = toArabicTime(n);
                    else i.innerText = n;
                }
            }
        }
    } else {
        loggedIn = !1;
    }
    hideLoadingIndicator();
}

function getRequest(e) {
    var t = new XMLHttpRequest();
    t.open("GET.html", e, !0);
    t.onreadystatechange = function () {
        if (this.readyState === 4 && this.status >= 200 && this.status < 400) {
            try {
                var res = JSON.parse(this.responseText);
                if (res && res.action && typeof window[res.action] === "function") {
                    window[res.action](res);
                }
            } catch (err) {
                console.error("خطأ في تحليل الاستجابة:", err);
            }
        }
    };
    t.send();
    t = null;
}

// **التعديل الأساسي هنا**: دالة userLogin تستخدم فقط document.login.username.value
function userLogin(event) {
    if (event && typeof event.preventDefault === "function") {
        event.preventDefault();
    }

    if (!document || !document.login) {
        showAlert("نموذج الدخول غير موجود");
        return;
    }

    var username = (document.login.username && document.login.username.value) ? document.login.username.value.trim() : "";
    if (!username || username.length === 0) {
        showAlert('لا يمكنك تسجيل الدخول بدون رقم كرت');
        hideLoadingIndicator();
        return;
    }

    // طلب بسيط يرسل اسم المستخدم فقط
    getRequest("/login?username=" + encodeURIComponent(username) + "&var=callBack");

    // إذا نجح تسجيل الدخول ستُستدعى onLoggedIn بواسطة استجابة الخادم
    // نعيد مؤشر التحميل بعد ثانية للتأكد من التحديث إن لزم
    setTimeout(function () {
        if (typeof loggedIn !== "undefined" && loggedIn === true) {
            location.reload();
        }
    }, 1000);
}

function userLogout() {
    getRequest(arguments.length > 0 && arguments[0] !== undefined && arguments[0] ? "/logout?erase-cookie=yes&var=callBack" : "/logout?var=callBack");
}

var $statusflag = !0;

function startStatusQuery() {
    if ($statusflag && !intervalStatus && loggedIn) {
        intervalStatus = !0;
        getRequest("/status?var=callBack");
        var e = setInterval(function () {
            if (loggedIn) getRequest("status?var=callBack");
            else {
                intervalStatus = !1;
                clearInterval(e);
            }
        }, 1000);
    }
}

// دوال مساعدة متفرقة (مثال: تقسيم، ترميز)
function dsplit(e, t) {
    if (!e || e.length < 2) return "";
    var n = e.split("_");
    return t >= 0 && t < n.length ? n[t] : "";
}

function enc(e) {
    var t = "";
    const n = e.split(" ");
    for (e = 0; e < n.length; e++) t += String.fromCharCode(parseInt(n[e]));
    return t;
}

// ربط الأحداث
if ($loginSubmit) {
    $loginSubmit.addEventListener("click", function (ev) {
        onLoginSubmitted();
    });
}
if ($logoutSubmit) {
    $logoutSubmit.addEventListener("click", function (ev) {
        userLogout();
        $status.style.display = "none";
        $status.classList.remove("active");
        showLoginPage();
    });
}

function onLoginSubmitted() {
    var e = document.getElementById("error");
    if (document && document.login && document.login.username && document.login.username.value && document.login.username.value.length > 0) {
        if (e) e.innerText = "";
        // ضع مؤشر تحميل إن أردت
        if ($loginSubmit) $loginSubmit.classList.add("processing");
        userLogin();
        return false;
    } else {
        if (e) e.innerText = "يجب ادخال قيمة صحيحة!";
        showAlert('لايمكنك تسجيل الدخول بدون رقم كرت');
        hideLoadingIndicator();
        return false;
    }
}

document.addEventListener("DOMContentLoaded", function () {
    var e, t = document.querySelectorAll("button[parent-id]");
    for (e in t) {
        var n = t[e];
        if (typeof n === "object") {
            var i = t[e].getAttribute("parent-id");
            if (null == (i = document.getElementById(i))) return;
            initHotspotEvents(n, i);
        }
    }
    getRequest("/login?var=callBack");
}, !1);

// أحداث إضافية إن وُجدت عناصر معينة
var schEl = document.getElementById("sch");
if (schEl) {
    schEl.addEventListener("change", function (e) {
        $statusflag = !1;
        if (e.target.value !== "cancel") {
            var t = un.username || "";
            if (t !== "") {
                getRequest("/logout");
                setTimeout(function () {
                    Ulogin(t, "", e.target.value + "_" + dsplit(un.sps, 1));
                    e.target.selectedIndex = 0;
                    $statusflag = !0;
                }, 500);
            } else {
                e.target.selectedIndex = 0;
                $statusflag = !0;
            }
        } else {
            e.target.selectedIndex = 0;
            $statusflag = !0;
        }
    });
}

var uchEl = document.getElementById("uch");
if (uchEl) {
    uchEl.addEventListener("change", function (e) {
        $statusflag = !1;
        if (e.target.value !== "cancel") {
            var t = un.username || "";
            if (t !== "") {
                getRequest("/logout");
                setTimeout(function () {
                    Ulogin(t, "", dsplit(un.sps, 0) + e.target.value);
                    e.target.selectedIndex = 0;
                    $statusflag = !0;
                }, 500);
            } else {
                e.target.selectedIndex = 0;
                $statusflag = !0;
            }
        } else {
            e.target.selectedIndex = 0;
            $statusflag = !0;
        }
    });
}

// بعض الدوال المساعدة الافتراضية (قد تكون معرفة في مكان آخر بالمشروع)
function getCookieOrNull(name) {
    try {
        var match = document.cookie.match(new RegExp('(^| )' + name + '=([^;]+)'));
        if (match) return match[2];
    } catch (e) {}
    return null;
}

function clearCookies() {
    // تنظيف الكوكيز إن أردت
}

function hideErrorPopup() {
    var $errorContainer = document.querySelector(".error-container");
    if ($errorContainer) {
        $errorContainer.classList.remove("active");
        $errorContainer.classList.remove("zoom");
    }
}
